'use strict';let catalogue,selected;const $=id=>document.getElementById(id);function message(text){$('message-text').textContent=text;$('message-dialog').showModal();}document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelector('.close-message').onclick=()=>$('message-dialog').close();document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));function contact(product){if(product?.quantity===0){message('This colourway is currently sold out. Check back for an update.');return;}if(!catalogue?.phone){message('The seller has not connected WhatsApp yet. This is a sample boutique; ordering will be available after the seller adds their contact details.');return;}const text=product?`Hi ${catalogue.shopName}! I'd like to enquire about ${product.name} (${Catalogue.money(product.price)}). Size: ${$('size').value}. Colour: ${$('color').value}. Please confirm availability, payment and delivery. Thank you!`:`Hi ${catalogue.shopName}! I'd like to ask about your collection.`;window.open('https://wa.me/'+catalogue.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');}document.querySelectorAll('[data-contact]').forEach(b=>b.onclick=()=>contact());document.querySelectorAll('[data-social]').forEach(b=>b.onclick=e=>{if(!catalogue)return;const kind=b.dataset.social,url=Catalogue.social(catalogue[kind],kind);if(url){b.href=url;}else{e.preventDefault();message('The seller has not connected '+(kind==='tiktok'?'TikTok':'Instagram')+' yet. Check back after the shop profile has been configured.');}});$('order-form').onsubmit=e=>{e.preventDefault();contact(selected);};function showProduct(p){selected=p;$('detail-image').src=p.image;$('detail-image').alt=p.name+' — front';const views=p.imageViews?Object.entries(p.imageViews).filter(([,src])=>src).map(([key,src])=>({src,label:({front:'Front',back:'Back',both:'Both views'})[key]})):(p.images?.length?p.images:[p.image]).map((src,i)=>({src,label:['Front','Back','Both views'][i]||'Photo '+(i+1)}));$('gallery-views').replaceChildren(...views.map(({src,label})=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-pressed',String(src===p.image));b.onclick=()=>{$('detail-image').src=src;$('detail-image').alt=p.name+' — '+b.textContent;[...$('gallery-views').children].forEach(x=>x.setAttribute('aria-pressed',String(x===b)));};return b;}));$('detail-category').textContent=p.category;$('detail-name').textContent=p.name;$('detail-price').textContent=Catalogue.money(p.price);$('detail-stock').textContent=Catalogue.stock(p);$('detail-stock').classList.toggle('sold-out',p.quantity===0);$('order-submit').disabled=p.quantity===0;$('order-submit').textContent=p.quantity===0?'Sold out':'Enquire on WhatsApp ↗';$('detail-description').textContent=p.description;for(const [id,values]of [['size',p.sizes],['color',p.colors]]){$(id).replaceChildren(...values.map(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;return o;}));}$('product-dialog').showModal();}function render(filter='All'){const featured=Catalogue.home(catalogue).featuredIds;const products=filter==='Featured'?(featured.length?featured.map(id=>catalogue.products.find(p=>p.id===id)).filter(Boolean):catalogue.products):catalogue.products.filter(p=>filter==='All'||p.category===filter);$('count').textContent=products.length+' PIECES';$('products').replaceChildren();if(!products.length){const p=document.createElement('p');p.textContent='No pieces in this collection just yet.';$('products').append(p);}products.forEach(p=>{const button=document.createElement('button');button.className='product';button.setAttribute('aria-label','View '+p.name);const photo=document.createElement('div');photo.className='product-image';const image=document.createElement('img');image.src=p.image;image.alt=p.name;image.loading='lazy';const tag=document.createElement('span');tag.textContent='GROWING IN SILENCE';const arrow=document.createElement('span');arrow.className='view';arrow.textContent='↗';photo.append(image,tag,arrow);const meta=document.createElement('div');meta.className='product-meta';const title=document.createElement('h3');title.textContent=p.name;const price=document.createElement('strong');price.textContent=Catalogue.money(p.price);meta.append(title,price);const details=document.createElement('p');details.textContent=p.colors.join(' / ');const stock=document.createElement('p');stock.className='stock-status';stock.classList.toggle('sold-out',p.quantity===0);stock.textContent=Catalogue.stock(p);button.append(photo,meta,details,stock);button.onclick=()=>showProduct(p);$('products').append(button);});}document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});if(catalogue)render(b.dataset.filter);});$('year').textContent=new Date().getFullYear();Catalogue.load().then(({data,live})=>{catalogue=data;Catalogue.applyHomepage(data);document.querySelectorAll('[data-social]').forEach(a=>{const url=Catalogue.social(data[a.dataset.social],a.dataset.social);if(url)a.href=url;const label=a.querySelector('small');if(label&&url){const handle=new URL(url).pathname.split('/').filter(Boolean).pop();label.textContent=handle?(handle.startsWith('@')?handle:'@'+handle):'';}});document.querySelectorAll('.shop-name').forEach(x=>{x.firstChild.textContent=data.shopName;});document.querySelectorAll('[data-brand]').forEach(x=>{x.textContent=data.shopName;});document.title=data.shopName+' — Growing in Silence';if(!live){$('preview-notice').hidden=false;$('preview-notice').textContent='DESIGN PREVIEW · Sample collection. Seller login and saving require the PHP server.';}render();}).catch(e=>{$('products').textContent=e.message;});
